import{c as e,S as r,j as l,m as i}from"./chunks/framework.8aa1YH_s.js";const m=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 4: Türkçedeki Vokaller (Ünlüler) ve Tasnifi","description":"","frontmatter":{},"headers":[],"relativePath":"4 Türkçedeki Vokaller (Ünlüler) ve Tasnifi.md","filePath":"4 Türkçedeki Vokaller (Ünlüler) ve Tasnifi.md"}'),n={name:"4 Türkçedeki Vokaller (Ünlüler) ve Tasnifi.md"};function t(s,a,k,o,d,u){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="turk-dil-bilgisi-serisi-4-turkcedeki-vokaller-unluler-ve-tasnifi" tabindex="-1">Türk Dil Bilgisi Serisi - 4: Türkçedeki Vokaller (Ünlüler) ve Tasnifi <a class="header-anchor" href="#turk-dil-bilgisi-serisi-4-turkcedeki-vokaller-unluler-ve-tasnifi" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 4: Türkçedeki Vokaller (Ünlüler) ve Tasnifi”">​</a></h1><p>Bir önceki bölümümüzde ses bilgisinin genel mahiyetine bakmış, vokallerin (ünlülerin) ses yolunda hiçbir engele takılmadan çıkan pürüzsüz sesler olduğunu belirtmiştik. Bu yazımızda, Türkiye Türkçesinin ses sistemini ayakta tutan 8 asli vokalimizi ve bu vokallerin Prof. Dr. Muharrem Ergin sistematiğine göre nasıl sınıflandırıldığını inceliyoruz.</p><hr><h2 id="_1-turkcenin-vokal-kadrosu" tabindex="-1">1. Türkçenin Vokal Kadrosu <a class="header-anchor" href="#_1-turkcenin-vokal-kadrosu" aria-label="Permalink to “1. Türkçenin Vokal Kadrosu”">​</a></h2><p>Modern Türkiye Türkçesinde kullanılan ve alfabemizde yer alan 8 temel vokal şunlardır: <strong>a, e, ı, i, o, ö, u, ü</strong></p><p>Muharrem Ergin&#39;e göre, asli Türkçe kelimelerde bu 8 sesin dışında uzun vokal (ā, î, û gibi) bulunmaz. Eğer bir kelimede uzun ünlü varsa, o kelime dilimize Arapça veya Farsçadan geçmiştir (Örn: <em>âyan, hâtıra, millî</em>).</p><hr><h2 id="_2-vokallerin-sınıflandırılması-tasnif-kriterleri" tabindex="-1">2. Vokallerin Sınıflandırılması (Tasnif Kriterleri) <a class="header-anchor" href="#_2-vokallerin-sınıflandırılması-tasnif-kriterleri" aria-label="Permalink to “2. Vokallerin Sınıflandırılması (Tasnif Kriterleri)”">​</a></h2><p>Ses yolundan çıkan hava akımının ağız boşluğundaki durumuna, dilin aldığı pozisyona ve dudakların şekline göre vokaller <strong>3 farklı kritere</strong> göre sınıflandırılır. Bir ünlünün tam karakterini belirlemek için bu üç özelliğini de bilmek gerekir.</p><h3 id="a-cıkıs-yerlerine-ve-dilin-durumuna-gore-kalın-ince" tabindex="-1">A) Çıkış Yerlerine ve Dilin Durumuna Göre (Kalın - İnce) <a class="header-anchor" href="#a-cıkıs-yerlerine-ve-dilin-durumuna-gore-kalın-ince" aria-label="Permalink to “A) Çıkış Yerlerine ve Dilin Durumuna Göre (Kalın - İnce)”">​</a></h3><p>Havanın ağız boşluğunun arkasından veya önünden çıkmasına; bu esnada dilin arkaya çekilmesine veya öne doğru gelmesine göre yapılan tasniftir:</p><ol><li><strong>Kalın Vokaller (Arka Vokaller):</strong> Dilin geriye çekilmesiyle, ağzın arka kısmında şekillenen seslerdir. <ul><li><strong>a, ı, o, u</strong></li></ul></li><li><strong>İnce Vokaller (Ön Vokaller):</strong> Dilin ileriye, alt dişlere doğru yaklaşmasıyla ağzın ön kısmında şekillenen seslerdir. <ul><li><strong>e, i, ö, ü</strong></li></ul></li></ol><h3 id="b-dudakların-durumuna-gore-duz-yuvarlak" tabindex="-1">B) Dudakların Durumuna Göre (Düz - Yuvarlak) <a class="header-anchor" href="#b-dudakların-durumuna-gore-duz-yuvarlak" aria-label="Permalink to “B) Dudakların Durumuna Göre (Düz - Yuvarlak)”">​</a></h3><p>Vokaller telaffuz edilirken dudakların aldığı fiziksel şekle göre yapılan tasniftir:</p><ol><li><strong>Düz Vokaller:</strong> Dudakların hiçbir büzülme veya yuvarlaklaşma göstermeden, doğal veya gergin durduğu seslerdir. <ul><li><strong>a, e, ı, i</strong></li></ul></li><li><strong>Yuvarlak Vokaller:</strong> Dudakların ileriye doğru uzayarak yuvarlak bir hal aldığı seslerdir. <ul><li><strong>o, ö, u, ü</strong></li></ul></li></ol><h3 id="c-agız-acıklıgına-gore-genis-dar" tabindex="-1">C) Ağız Açıklığına Göre (Geniş - Dar) <a class="header-anchor" href="#c-agız-acıklıgına-gore-genis-dar" aria-label="Permalink to “C) Ağız Açıklığına Göre (Geniş - Dar)”">​</a></h3><p>Ses telleri titreşip hava ağza geldiğinde, alt çenenin durumuna ve dil ile damak arasındaki mesafenin (açıklığın) derecesine göre yapılan tasniftir:</p><ol><li><strong>Geniş Vokaller:</strong> Alt çenenin aşağıya inmesiyle ağız boşluğunun genişlediği durumlarda çıkan seslerdir. <ul><li><strong>a, e, o, ö</strong></li></ul></li><li><strong>Dar Vokaller:</strong> Alt çenenin yukarıya doğru yakın durduğu ve dil ile damak arasındaki mesafenin dar olduğu durumlarda çıkan seslerdir. <ul><li><strong>ı, i, u, ü</strong></li></ul></li></ol><hr><h2 id="_3-muharrem-ergin-in-klasik-vokal-tablosu" tabindex="-1">3. Muharrem Ergin&#39;in Klasik Vokal Tablosu <a class="header-anchor" href="#_3-muharrem-ergin-in-klasik-vokal-tablosu" aria-label="Permalink to “3. Muharrem Ergin&#39;in Klasik Vokal Tablosu”">​</a></h2><p>Yukarıdaki 3 farklı kriteri tek bir sistemde birleştirdiğimizde ortaya çıkan ve Türk dil bilgisinin anayasası sayılan vokal tablosu şu şekildedir:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Ağız Açıklığı</th><th style="text-align:center;">Düz / Kalın</th><th style="text-align:center;">Düz / İnce</th><th style="text-align:center;">Yuvarlak / Kalın</th><th style="text-align:center;">Yuvarlak / İnce</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Geniş Vokaller</strong></td><td style="text-align:center;"><strong>a</strong></td><td style="text-align:center;"><strong>e</strong></td><td style="text-align:center;"><strong>o</strong></td><td style="text-align:center;"><strong>ö</strong></td></tr><tr><td style="text-align:left;"><strong>Dar Vokaller</strong></td><td style="text-align:center;"><strong>ı</strong></td><td style="text-align:center;"><strong>i</strong></td><td style="text-align:center;"><strong>u</strong></td><td style="text-align:center;"><strong>ü</strong></td></tr></tbody></table><p>Bu tabloyu akılda tutmak, Türkçenin en büyük ses kanunu olan <strong>&quot;Ünlü Uyumları&quot;</strong> konusunu tamamen çözmenin anahtarıdır.</p><h3 id="tablodan-cıkarılacak-pratik-bilgiler" tabindex="-1">Tablodan Çıkarılacak Pratik Bilgiler: <a class="header-anchor" href="#tablodan-cıkarılacak-pratik-bilgiler" aria-label="Permalink to “Tablodan Çıkarılacak Pratik Bilgiler:”">​</a></h3><ul><li><strong>a:</strong> Kalın, düz, geniş bir vokaldir.</li><li><strong>e:</strong> İnce, düz, geniş bir vokaldir.</li><li><strong>ü:</strong> İnce, yuvarlak, dar bir vokaldir.</li><li><strong>ı:</strong> Kalın, düz, dar bir vokaldir.</li></ul><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Türkçedeki 8 vokal; kalın-ince, düz-yuvarlak ve geniş-dar olmak üzere kusursuz bir simetri ve matematiksel denge üzerine kuruludur. Dilimizin sahip olduğu bu fonetik simetri, kelimelerin telaffuzunu kolaylaştırır ve Türkçeye o kendine has akıcı musikisini kazandırır.</p><p>Serimizin 5. bölümünde, bu öğrendiğimiz vokal tablosunu doğrudan pratiğe dökeceğiz ve Türkçenin en önemli ses kuralı olan <strong>&quot;Büyük ve Küçük Ünlü Uyumları&quot; (Vokal Uyumları)</strong> konusunu tüm istisnalarıyla birlikte ele alacağız.</p><p>Yola devam, takipte kal aslanım!</p>',30)])])}const h=e(n,[["render",t]]);export{m as __pageData,h as default};
